import React from "react";
import TextField from "@mui/material/TextField";


const paperSizes = {
  "A2": { length: 594, width: 420 },
  "A3": { length: 420, width: 297 },
  "A4": { length: 297, width: 210 },
  "A5": { length: 210, width: 148 },
  "A6": { length: 148, width: 105 },
  "DL": { length: 220, width: 110 } // DIN Lang
};


export interface WeightInfoProps{
    length: number;

    width: number;

    grammage: number;

    numberOfSheets: number;

    setNumberOfSheets: (num: number) => void;
}


const WeightInfo = ({length, width, grammage, numberOfSheets, setNumberOfSheets} : WeightInfoProps)=>{
    return(
        <>
            <p><strong>Weight:</strong> {length * width * grammage * numberOfSheets} g</p>

            <TextField
                style={{margin:100}}
                type="number"
                label="Number of sheets"
                value={numberOfSheets}
                onChange={(val)=>{setNumberOfSheets(Number(val.target.value))}}
            />

        </>
    )
}



export default WeightInfo;
